  "museumPatch": {
    "title": "奶蛙现代艺术馆",
    "titleEn": "Milk Frog Museum of Modern Art",
    "subtitle": "从一张脸，看到它周围的规则",
    "intro": "从镜中的背影到失去水的瓷砖，从一枚未读标记到只剩黄色的方块，222件作品追问：一个角色可以改变多少，仍与原来的自己发生关系？沿五个展厅观看，也可按媒介和编号查阅。",
    "headline": "一只熟悉的身体，\n世界不再严丝合缝。",
    "featuredId": "011-incompatible-lunch",
    "statement": "先认出它，再看它与周围事物的关系。每一次改写，都要说明哪些线索被保住，哪些规则被改变。",
    "manifestoTitle": "把变化放在\n可以比较的位置。",
    "manifesto": [
      "这次编排从“怎样认出同一个角色”开始，逐步转向“周围的关系怎样改变它”。稳定的黄色身体使不同作品能够彼此参照；它也会失去正脸、改变材质、被放大到房间装不下，或拆成眼睛、嘴和色块。策展的工作，是把这些变化放在可以比较的位置，而非用一个风格名称盖住它们的差别。",
      "五个展厅依次经过辨认、姿势、日常空间、复制与拆分、抽象构成。每厅都有自己的转折：完整身体之后接遮挡，静止招手之后接循环，单张肖像之后接批量排列，熟悉的黄色最后脱离了身体。这是一条问题递进的路线，不是艺术史分期，也不把较晚编号理解成较高完成度。",
      "历史作品在这里提供可辨认的构图与操作：镜像、环舞、双人整体、肖像序列、摄影蒙太奇与正交格网。每件改编应当能够说明保留了哪一种关系，又改变了什么。将角色放入一幅名画并不自动产生批判；画面是否成立，仍要回到支撑、遮挡、距离、视点与节奏。原作资料与本项目的当代解释分别列出。",
      "“失配”指那些能被具体指出的关系偏移：身体完整而空间不连续，地面坚硬而形状如水，轮廓向前而色块落后。它也需要相对稳定的作品作对照。《倒牛奶的奶蛙》里的手、壶与奶流必须配合，《相拥的奶蛙》的环抱必须在体量上成立。全馆因而保留劳动、亲近和停顿，不把一切都归为错误或荒诞。",
      "本项目的创作、筛选、展签与研究彼此相关。策展文本可以提出读法，不能替作品证明观众已经被治愈、冒犯或说服。研究区继续追问这些判断如何取证；版本对照则让部分选择留在图像之间，而不是只留在一段解释里。"
    ],
    "rightsNote": "本站展示奶蛙题材的AI辅助图像与数字三维再创作，不代表角色权利方、历史作品作者或收藏机构。相关角色与被引用作品的权利归各自权利人；本馆不为第三方内容授予开放许可。历史参考以来源链接说明，不再发行其参考原图。",
    "editionNote": "网页展示版；不含完整分辨率下载。",
    "archiveNote": "八月旧作归档：20 件作品、6 张早期版本；旧作题名与修订关系保留，展签与解读在本次归档时补充。"
  },
