    "preface": [
      "一只黄色身体站在镜前，镜子没有交出它的脸。换一幅图，它已坐好，桌子、盘子和椅子却没能组成同一间屋子。再往后，眼睛、手脚和腹部陆续退场，题名仍请我们在一块黄色里寻找奶蛙。",
      "奶蛙现代艺术馆是一项在线创作与研究计划。这里收录AI辅助图像、Blender三维作品和循环影像，以奶蛙及其眼睛、色彩为反复出现的线索，观察身份、动作、空间和复制怎样相互牵制。“展厅”是网页中的观看章节；雕塑的青铜、石材与陶釉是数字材质，画面的裂纹、纸边和套印痕迹也须依作品记录区分。",
      "你可以从第一厅顺序观看，也可以直接进入一件作品。建议先留意一个具体关系：书为什么能正常照镜子，短手怎样托住红色圆章，黄色又在哪里越过了轮廓。之后再读题名、展签与研究。文字提供一条路，图像仍保留不服从这条路的可能。"
    ],
