          "两只罐头把身体暂时换成包装格式，之后的蒙太奇又将眼、嘴、四肢与机械图形分开。观看、展示和计量在画面上成为可拼装的功能。题名可以将这种分工引向流量与平台问题，但这些作品没有提供推荐数据或真实商品记录；社会机制的判断，需要另到研究区查证。",
