  "about": {
    "title": "关于这项在线计划",
    "intro": "奶蛙现代艺术馆使用数字展览的方式，保存同一角色在不同构图、媒介和命名中留下的差异。它的“展厅”是观看章节，“馆藏”是作品目录；本站并非实体博物馆的参观服务。",
    "productionTitle": "创作、版本与研究说明",
    "sections": [
      {
        "title": "这是一项怎样的创作",
        "paragraphs": [
          "本站以AI辅助图像、Blender程序建模、数字材质与渲染、关键帧动画等方式制作和组织作品。项目方向与发布决定来自项目发起者；dot（AI助手）在授权范围内参与方案、操作、筛选检查及文字整理。具体媒介以各件作品的说明为准，不能用一个统一标签抹去不同工序。旧作按现有记录归档；完整过程尚未恢复的，不补写工具型号、生成步骤或个人贡献。",
          "作品与文字中的第一人称属于项目叙述与创作说明。它不表示AI曾亲历画面中的事件、具有潜意识，或能仅凭署名取得全部作者权利。"
        ]
      },
      {
        "title": "材质、动作与时间的边界",
        "paragraphs": [
          "青铜、石灰岩、大理石和陶釉指数字模拟的材料外观，本站并未声称陈列这些实体雕塑。图像中的纸张、滴洒和拼贴边缘也可能由生成模型描绘，不能直接当作手工物质过程的痕迹。",
          "《走慢半步的黄色》模拟局部套印失配，并非严格的物理分色实验；《影子还是走楼梯》采用影子拟人化；《拉链里的午休》是二维插画；《先睡，图慢慢加载》的像素与棋盘格是画面内容，不是实时加载记录。《影子请留步》描绘影子成为黑带的视觉不可能，并非实际光学装置、现场安装或运动演示。",
          "《退潮以后，眼睛还在》把同心色环描绘为潮滩，并以浴缸塞制造尺度错位；海水从黑瞳漏走是图像设定，不是实地排水装置或潮汐记录。",
          "《今日小雨，手工现做》让家用压面机把云加工成雨。水彩、纸张和干彩铅外观是数字模拟，画面也不是实际机械加工或天气实验。",
          "《号码替我排队》的黑白墨块、磨损边缘与半调网点是数字生成的印刷模拟。号码纸自行排队是画内的替身机制，不是实际办事程序，也不声称真实印制。",
          "《褶皱里的一小块平地》的撕纸边缘、纸面纹理与拼贴空间为数字模拟，不是实物纸雕或实际拼贴。"
        ]
      },
      {
        "title": "如何理解“原创构图”",
        "paragraphs": [
          "部分作品关联具体历史作品，部分以项目角色参考组织新的场景。“原创构图”说明本项目没有为该件指定一幅历史原作作为构图来源，不等于宣称角色本身原创，也不代表第三方权利已经清理。",
          "来源区将关联作品或艺术家资料与本项目解释分开。艺术家概览页用于背景参照，具体藏品页用于核对相应作品；链接不表示对方为本馆的解读背书。"
        ]
      },
      {
        "title": "版本为什么留下",
        "paragraphs": [
          "现有图录包含222件主展品；另有6张早期版本，附属于A03、A05、A06、A07和A08。它们用于比较图像选择，不另计为主展品。Blender的S01–S09九项研究共同计为一件组作；组内单件与七个附加视角保留，也不另计为新作品。",
          "八月旧作的原题名与版本关系保留，展签和解读在归档时补充。旧题名中的“奶龙”或“Nailong”是历史记录的一部分，不据此把所有形象认定为官方奶龙，也不将归档日期倒写成首次创作日期。"
        ]
      },
      {
        "title": "研究与展览的关系",
        "paragraphs": [
          "研究文章与作品、展签处于同一项目的生产和解释过程。它们提供可核对的形式分析、有限的过程证据与理论问题；这份接近材料的优势，也带来自我印证和成功样本筛选的风险。",
          "本站研究是研究型文章，并非已经经过期刊同行评审的论文。有关观众的喜爱、情绪、身份认同、分享行为与平台推荐，凡未取得独立证据的，均保留为问题或假设。"
        ]
      }
    ],
    "rightsTitle": "作品、角色与引用",
    "rightsNote": "本站展示奶蛙题材的AI辅助图像与数字三维再创作，不代表角色权利方、历史作品作者或收藏机构。相关角色与被引用作品的权利归各自权利人；本馆不为第三方内容授予开放许可。历史参考以来源链接说明，不再发行其参考原图。",
    "identityNote": "本站“奶蛙”指本项目所使用的黄色梨形角色及相关作品。项目内的造型参照不等于官方奶龙设定、全网统一标准或已经核实的完整起源谱系。",
    "inspiration": {
      "title": "灵感与致谢",
      "sourceTitle": "奶蛙博物馆 · MUSÉE DU MILK FROG",
      "sourceUrl": "https://works.cohub.live/w/157e937b-95da-4c17-add4-f916e37c3574/milk-frog-museum/1980bbadcb26/content/index.html",
      "paragraphs": [
        "本项目受到“奶蛙博物馆 · MUSÉE DU MILK FROG”的启发。该站把奶蛙置入艺术史图像，并以图录、身份资料与版本记录组织观看，提示了让同一角色反复进入不同图像秩序的可能。",
        "奶蛙现代艺术馆由此展开另一项在线创作与研究计划，以独立馆名、主题编排和策展文本明确自身范围。这里的致谢指向创作启发，不表示合作、授权或相互背书，也不将灵感来源网站的“官方”表述当作角色权利归属的证明。"
      ]
    }
  },
